import subprocess, sys, json
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "-U", "diffusers", "transformers", "accelerate"], check=False)
import torch
from diffusers import AutoPipelineForText2Image, DPMSolverMultistepScheduler
JOB = json.loads('{"variants": 3, "style": "digital painting, semi-realistic storybook illustration, painterly brush strokes, cinematic lighting, rural north India village, emotional, highly detailed", "negative": "text, watermark, signature, photo, 3d render, deformed hands, extra fingers, extra limbs, distorted face, blurry, low quality, frame, border", "shots": {"s01": "wide shot, a lone young Indian man in a white kurta walking away on a dirt path through a vast blooming yellow mustard field, golden sunset sky, seen from behind", "s02": "a beautiful young Indian woman in a yellow salwar suit running through a yellow mustard field, looking back over her shoulder laughing, long black braid, red dupatta flying in the wind, golden hour light", "s03": "a young Indian man in white kurta and a young woman in yellow suit with red dupatta sitting close together under a huge banyan tree in a village, seen from behind, warm evening light, a rope swing hanging from a branch", "s04": "extreme close-up of two hands, a woman\'s hand with red glass bangles placing a small folded paper letter into a man\'s open palm, warm golden light, soft blurred background", "s05": "a village fair at night, glowing ferris wheel, colorful string lights and lanterns, a young couple standing together holding hands seen from behind, woman in red dupatta, festive warm glow", "s06": "a young Indian couple sheltering from heavy monsoon rain under the tin roof of a small roadside tea stall, glowing lantern, looking at each other shyly, wet street, blue rainy dusk", "s07": "night, a distant wedding procession with bright lights, lanterns and fireworks in a village lane, in the dark foreground a lone young man in white kurta stands watching, seen from behind, melancholic", "s08": "portrait of a young Indian bride in a red lehenga and veil with gold jewellery, looking back over her shoulder with sad teary eyes, marigold garlands, warm oil lamps, soft focus", "s09": "a lone young Indian man sitting on a charpai cot on a village rooftop at night under a sky full of stars, holding a paper letter, an oil lantern glowing beside him, lonely, deep blue tones", "s10": "an empty wooden rope swing hanging from a huge banyan tree at blue misty dusk, fallen leaves on the ground, nobody, lonely quiet atmosphere", "s11": "side view of a sad young Indian man looking out of an old train window, raindrops on the glass, blurred green fields passing outside, cool blue tones, reflective mood", "s12": "a vast mustard field at night under a brilliant starry sky with glowing fireflies, a lone man seen from behind looking up, far away a faint glowing silhouette of a woman with a flowing dupatta, magical, bittersweet"}}')
pipe = AutoPipelineForText2Image.from_pretrained("Lykon/dreamshaper-xl-v2-turbo", torch_dtype=torch.float16, variant="fp16").to("cuda")
pipe.scheduler = DPMSolverMultistepScheduler.from_config(pipe.scheduler.config, algorithm_type="sde-dpmsolver++", use_karras_sigmas=True)
for name, prompt in JOB["shots"].items():
    for v in range(JOB["variants"]):
        g = torch.Generator("cuda").manual_seed(1000 + v * 77 + len(name) + sum(map(ord, name)))
        im = pipe(JOB["style"] + ", " + prompt, negative_prompt=JOB["negative"], width=768, height=1344, num_inference_steps=8, guidance_scale=2.0, generator=g).images[0]
        im.save(f"{name}-v{v}.jpg", quality=94); print("done", name, v, flush=True)
